-- Schema-only synthetic fixture; no production records.
create table mschool.users (
  id text primary key,
  name text not null,
  role_type text default '學生',
  gender text,
  birth date,
  school text,
  grade text,
  phone text,
  address text,
  guardian_name text,
  guardian_phone text,
  points integer default 0,
  status text default '在班',
  note text,
  created_at timestamp with time zone default now(),
  avatar_url text,
  id_card text,
  class_section text,
  home_phone text,
  mentor_name text,
  guardian_relation text,
  emergency_name text,
  emergency_relation text,
  emergency_phone text,
  welfare_status text,
  siblings_count text,
  family_economy text,
  medical_history text,
  dietary_restrictions text,
  special_needs text,
  face_descriptor jsonb,
  parent_name text,
  parent_relation text,
  parent_phone text,
  family_status text,
  health_notes text
);
